// js
// MSF: the lesser of the leave's gross pay with the employer's CPF on it and the cap, which includes that CPF
const terms = ctx.subject.employment.terms;
const facts = ctx.subject.employment.employee_extension_data;
const perWeek = Number(terms.normal_days_per_week);
const basic = ctx.month_wage;
const allowance = get(terms, 'allowances.FIXED_MONTHLY.amount', 0);
const fixed = typeof allowance === 'number' ? allowance : get(allowance, 'value', 0);
const monthly = get(terms, 'rate.unit', 'MONTHLY') === 'MONTHLY' && basic > 0;
const gross = monthly ? ctx.day_rate * ((basic + fixed) / basic) : ctx.day_rate;
// CPF stops at the OW ceiling
const wage = monthly ? ctx.day_rate * (Math.min(basic + fixed, ctx.lookup.ordinary_ceiling) / basic) : ctx.day_rate;
const employerRate = () => {
	const status = get(terms, 'residency_status', '');
	if (!ctx.lookup.local_residencies.includes(status)) return 0;
	const dob = get(ctx.subject.employment.payroll, 'date_of_birth', '');
	if (dob === '') return 0;
	const from = ctx.run.salary_coverage.from;
	const age = age_on(dob, add_days(month_start(from), -1));
	const elections = get(facts, 'statutory.CPF', {});
	const since = get(facts, 'residency_since', '');
	const graduated = status === 'PERMANENT_RESIDENT' && since !== '';
	const early = graduated && get(elections, 'spr_full_rates', false) !== true;
	const suffix = get(elections, 'spr_employer_full_rates', false) === true ? '_full_employer' : '';
	let phase = 'full';
	if (early && from <= String(month_end(add_years(since, 2)))) phase = 'second_year' + suffix;
	if (early && from <= String(month_end(add_years(since, 1)))) phase = 'first_year' + suffix;
	const bands = ctx.lookup.cpf_bands.filter((band) => band.phase === phase);
	let key = bands[0].key;
	for (const band of bands) if (age >= band.age) key = band.key;
	return get(ctx.lookup.cpf_rates, key + '_total', 0) - get(ctx.lookup.cpf_rates, key + '_high', 0);
};
const weekly = get(ctx.lookup, 'weekly_limit', null);
const cap = weekly === null ? ctx.lookup.daily_limit : weekly / perWeek;
return Number(ctx.entry.quantity) * Math.min(gross + employerRate() * wage, cap);

